-- ===== DEMO 2/5 : profils d'exemple 1/2 (personnes fictives, illustrations abstraites, numeros fictifs 06 39 98) =====
select ('00000000-0000-4000-8000-' || lpad(g::text, 12, '0'))::uuid, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated',
       'demo' || g || '@objectif.invalid', '', now(), now(), now(), '{"provider":"email","providers":["email"]}', '{}'
from generate_series(301, 330) g on conflict (id) do nothing;

